#!/usr/bin/env python3
"""
Analyze all responses and compare against the correct classification string.
"""

import re

# Read the correct classification
with open('/workspace/correct_classification.txt', 'r') as f:
    correct = f.read().strip()

print(f"Correct classification (length {len(correct)}):")
print(correct)
print()

# Read and analyze each response
responses = {}
for letter in 'ABCDEFGH':
    path = f'/input_artifacts/proposed_solutions/response_{letter}.md'
    with open(path, 'r') as f:
        content = f.read()
    responses[letter] = content

    # Extract any P/N strings from the content
    # Look for sequences of P and N characters
    pn_strings = []

    # Find all lines that might contain classification strings
    for line in content.split('\n'):
        # Remove whitespace and look for P/N sequences
        clean = ''.join(c for c in line if c in 'PN')
        if len(clean) >= 10:  # Only consider substantial strings
            pn_strings.append(clean)

    print(f"\n=== Response {letter} ===")
    print(f"Content length: {len(content)}")

    if pn_strings:
        for i, s in enumerate(pn_strings):
            print(f"P/N string {i+1} (length {len(s)}): {s[:80]}..." if len(s) > 80 else f"P/N string {i+1} (length {len(s)}): {s}")

            if len(s) == 131:
                if s == correct:
                    print("  -> MATCHES CORRECT!")
                else:
                    # Find first difference
                    for j, (c1, c2) in enumerate(zip(s, correct)):
                        if c1 != c2:
                            print(f"  -> First difference at position {j}: got '{c1}', expected '{c2}'")
                            break
    else:
        print("No P/N strings found with length >= 10")

    # Check for specific patterns in the content
    print(f"\nKey content analysis:")

    # Check base case statement
    if '0 = P' in content or 'dp[0] = P' in content or 'position 0 is P' in content.lower():
        print("  - Explicitly states position 0 is P")
    elif '0 = N' in content or 'position 0 is N' in content.lower():
        print("  - WRONG: states position 0 is N")

    # Check for move set
    if 'triangular' in content.lower() and 'square' in content.lower():
        print("  - Mentions both triangular and square numbers")
    elif 'square' in content.lower():
        print("  - Only mentions squares")
    elif 'triangular' in content.lower():
        print("  - Only mentions triangulars")

    # Check for specific move lists
    move_lists = re.findall(r'\{[^}]+\}', content)
    for ml in move_lists:
        if any(str(x) in ml for x in [1, 3, 4, 6]):
            print(f"  - Contains move list: {ml[:80]}..." if len(ml) > 80 else f"  - Contains move list: {ml}")

# Summary comparison
print("\n" + "="*60)
print("SUMMARY")
print("="*60)

for letter in 'ABCDEFGH':
    content = responses[letter]

    # Find the longest P/N string
    pn_strings = []
    for line in content.split('\n'):
        clean = ''.join(c for c in line if c in 'PN')
        if len(clean) >= 10:
            pn_strings.append(clean)

    longest = max(pn_strings, key=len) if pn_strings else ""

    match_status = "UNKNOWN"
    if longest == correct:
        match_status = "CORRECT"
    elif len(longest) != 131:
        match_status = f"WRONG LENGTH ({len(longest)})"
    else:
        match_status = "WRONG VALUES"

    print(f"Response {letter}: {match_status}")

